const CACHE='fourth-dimension-v3';
const CORE=['./','./index.html','./styles.css','./app.js','./service.html','./service.css','./service.js','./tools/','./tools/index.html','./tools/tools.css','./tools/tools.js','./brief/','./legal/privacy.html','./legal/terms.html','./legal/cookies.html','./legal/refunds.html','./legal/ai-disclaimer.html','./legal/legal.css','./journal/','./shop/','./assets/logo.webp','./assets/hero-poster.jpg','./assets/app-icon-192-transparent.png','./assets/app-icon-512-transparent.png'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(CORE)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET')return;event.respondWith(fetch(event.request).then(response=>{const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));return response}).catch(()=>caches.match(event.request).then(hit=>hit||caches.match('./index.html'))))});
